import { test, expect } from 'bun:test';
import { deepMerge } from '../src/merge.js';
test('merges nested objects, override wins', () => {
  expect(deepMerge({ a: 1, n: { x: 1, y: 2 } }, { b: 2, n: { y: 9 } })).toEqual({ a: 1, b: 2, n: { x: 1, y: 9 } });
});
test('arrays are replaced, not merged', () => expect(deepMerge({ l: [1, 2, 3] }, { l: [4] })).toEqual({ l: [4] }));
test('inputs are not changed', () => {
  const base = { n: { x: 1 } }, over = { n: { y: 2 } };
  deepMerge(base, over);
  expect(base).toEqual({ n: { x: 1 } });
  expect(over).toEqual({ n: { y: 2 } });
});

