import { test, expect } from 'bun:test';
import { deepMerge } from '../src/merge.js';
test('an own __proto__ key does not pollute anything', () => {
  const over = JSON.parse('{"__proto__":{"isAdmin":true},"ok":1}');
  const out = deepMerge({ a: 1 }, over);
  expect({}.isAdmin).toBeUndefined();
  expect(out.isAdmin).toBeUndefined();
  expect(Object.getPrototypeOf(out)).toBe(Object.prototype);
  expect(out.ok).toBe(1);
});
test('a nested __proto__ or constructor.prototype key does not pollute Object.prototype', () => {
  deepMerge({ n: {} }, JSON.parse('{"n":{"__proto__":{"nested":true}}}'));
  deepMerge({}, JSON.parse('{"constructor":{"prototype":{"viaCtor":true}}}'));
  expect({}.nested).toBeUndefined();
  expect({}.viaCtor).toBeUndefined();
});
